SELECT COUNT(*) AS count_weak_white_bordered_cards
FROM cards
WHERE borderColor = 'white' AND CAST(power AS INTEGER) < 3;

SELECT COUNT(*) AS total_rulings_for_fireball
FROM rulings
WHERE uuid = (SELECT uuid FROM cards WHERE name = 'Fireball');

SELECT COUNT(*) AS count_of_printings
FROM cards
WHERE power > 3 AND power <= 10;

SELECT COUNT(DISTINCT foreign_data.language) AS foreign_language_count
FROM foreign_data
WHERE foreign_data.name = 'Swamp';

WITH majors_with_members AS (
  SELECT DISTINCT major_id
  FROM member
), total_majors AS (
  SELECT COUNT(*) AS total_count
  FROM major
), majors_no_members AS (
  SELECT COUNT(*) AS no_member_count
  FROM major
  WHERE major_id NOT IN (SELECT major_id FROM majors_with_members)
)
SELECT ROUND((no_member_count * 100.0) / total_count, 2) AS percentage_no_members
FROM total_majors, majors_no_members;

SELECT MAX(CAST(RNP AS REAL)) AS highest_anti_rnp_ab
FROM Laboratory
WHERE CRE < 1.5;
